-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/zones/Northern_San_dOria/npcs/Olbergieut.lua"]={["Path"]="scripts/zones/Northern_San_dOria/npcs/Olbergieut.lua",["SHA256"]="d78f6decab419e10c5a6523adf27e1663b910319865c7fdda7963218c63b4e9c",["Text"]="-----------------------------------\n-- Area: Northern San d'Oria\n--  NPC: Olbergieut\n-- !pos 91 0 121 231\n-- Starts and Finishes Quest: Gates of Paradise\n-----------------------------------\nlocal ID = zones[xi.zone.NORTHERN_SAN_DORIA]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local gates = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.GATES_TO_PARADISE)\n\n    if player:hasKeyItem(xi.keyItem.SCRIPTURE_OF_WATER) then\n        player:startEvent(620)\n    elseif gates == xi.questStatus.QUEST_ACCEPTED then\n        player:showText(npc, ID.text.OLBERGIEUT_DIALOG, xi.keyItem.SCRIPTURE_OF_WIND)\n    elseif\n        player:getFameLevel(xi.fameArea.SANDORIA) >= 2 and\n        gates == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(619)\n    else\n        player:startEvent(612)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 619 and option == 0 then\n        player:addQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.GATES_TO_PARADISE)\n        npcUtil.giveKeyItem(player, xi.keyItem.SCRIPTURE_OF_WIND)\n    elseif csid == 620 then\n        if npcUtil.giveItem(player, xi.item.COTTON_CAPE) then\n            player:completeQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.GATES_TO_PARADISE)\n            player:addFame(xi.fameArea.SANDORIA, 20)\n            player:addTitle(xi.title.THE_PIOUS_ONE)\n            player:delKeyItem(xi.keyItem.SCRIPTURE_OF_WATER)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Northern_San_dOria/npcs/Pagisalis.lua"]={["Path"]="scripts/zones/Northern_San_dOria/npcs/Pagisalis.lua",["SHA256"]="dfbe9cbb9abd4ad23b3f06eaaf5aa81d56b6e772a795cf2561bd22381fb4beac",["Text"]="-----------------------------------\n-- Area: Northern San d'Oria\n--  NPC: Pagisalis\n-- Involved In Quest: Enveloped in Darkness\n-- !zone 231\n-----------------------------------\nlocal ID = zones[xi.zone.NORTHERN_SAN_DORIA]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.UNDYING_FLAMES) == xi.questStatus.QUEST_ACCEPTED then\n        if\n            trade:hasItemQty(xi.item.LUMP_OF_BEESWAX, 2) and\n            trade:getItemCount() == 2\n        then\n            player:startEvent(563)\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local sanFame = player:getFameLevel(xi.fameArea.SANDORIA)\n    local undyingFlames = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.UNDYING_FLAMES)\n\n    if sanFame >= 2 and undyingFlames == xi.questStatus.QUEST_AVAILABLE then\n        player:startEvent(562)\n    elseif undyingFlames == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(565)\n    elseif undyingFlames == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(566)\n    else\n        player:startEvent(564)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 562 and option == 0 then\n        player:addQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.UNDYING_FLAMES)\n    elseif csid == 563 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.FRIARS_ROPE)\n        else\n            player:tradeComplete()\n            player:addTitle(xi.title.FAITH_LIKE_A_CANDLE)\n            player:addItem(xi.item.FRIARS_ROPE)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.FRIARS_ROPE)\n            player:addFame(xi.fameArea.SANDORIA, 20)\n            player:completeQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.UNDYING_FLAMES)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Northern_San_dOria/npcs/Shomo_Pochachilo.lua"]={["Path"]="scripts/zones/Northern_San_dOria/npcs/Shomo_Pochachilo.lua",["SHA256"]="c4c405c09260a42f388eefb253a72e918c53baaec3ceccde320335306e4d8df3",["Text"]="-----------------------------------\n-- Area: Northern San d'Oria\n--  NPC: Shomo Pochachilo\n-- !pos 28.369 -0.199 30.061 231\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    -- TODO: Verify this, and move to quest script\n    local questFatherAndSon = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.FATHER_AND_SON)\n\n    if questFatherAndSon == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(696)\n    else\n        player:startEvent(675)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Port_Bastok/npcs/Alib-Mufalib.lua"]={["Path"]="scripts/zones/Port_Bastok/npcs/Alib-Mufalib.lua",["SHA256"]="614e59978d4ea1c3d8d8ed5957e5d37d8dcdbd071c0c1d5fca60ce458dd0ef9c",["Text"]="-----------------------------------\n-- Area: Port Bastok\n--  NPC: Alib-Mufalib\n-- Type: Warp NPC\n-- !pos 116.080 7.372 -31.820 236\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        trade:getGil() == 300 and\n        trade:getItemCount() == 1 and\n        player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.LURE_OF_THE_WILDCAT) and\n        player:getCurrentMission(xi.mission.log_id.TOAU) > xi.mission.id.toau.IMMORTAL_SENTRIES\n    then\n        -- Needs a check for at least traded an invitation card to Naja Salaheem\n        player:startEvent(379)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    if player:getCurrentMission(xi.mission.log_id.TOAU) >= xi.mission.id.toau.PRESIDENT_SALAHEEM then\n        player:startEvent(378)\n    else\n        player:startEvent(361)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 379 then\n        player:tradeComplete()\n        xi.teleport.to(player, xi.teleport.id.WHITEGATE)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Port_Bastok/npcs/Dalba.lua"]={["Path"]="scripts/zones/Port_Bastok/npcs/Dalba.lua",["SHA256"]="35e85b2da98d48b5c305143f5082f432a68209b40c97aeb9ffed579bf23680f9",["Text"]="-----------------------------------\n-- Area: Port Bastok\n--  NPC: Dalba\n-- Type: Past Event Watcher\n-- !pos -174.101 -7 -19.611 236\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    -- Bastok Missions.\n    local bastokMissions = 0xFFFFFFFE\n    if player:hasCompletedMission(xi.mission.log_id.BASTOK, xi.mission.id.bastok.FETICHISM) then\n        bastokMissions = bastokMissions - 2 -- Fetichism.\n    end\n\n    if player:hasCompletedMission(xi.mission.log_id.BASTOK, xi.mission.id.bastok.TO_THE_FORSAKEN_MINES) then\n        bastokMissions = bastokMissions - 4 -- To the Forsaken Mines.\n    end\n\n    -- Bastok Quests.\n    local bastokQuests = 0xFFFFFFFE\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.BEAUTY_AND_THE_GALKA) then\n        bastokQuests = bastokQuests - 2         -- Beauty and the Galka.\n    end\n\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.WELCOME_TO_BASTOK) then\n        bastokQuests = bastokQuests - 4         -- Welcome to Bastok.\n    end\n\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.GUEST_OF_HAUTEUR) then\n        bastokQuests = bastokQuests - 8         -- Guest of Hauteur.\n    end\n\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.CIDS_SECRET) then\n        bastokQuests = bastokQuests - 16        -- Cid's Secret.\n    end\n\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.THE_USUAL) then\n        bastokQuests = bastokQuests - 32        -- The Usual.\n    end\n\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.LOVE_AND_ICE) then\n        bastokQuests = bastokQuests - 64        -- Love and Ice(pt.1).\n        bastokQuests = bastokQuests - 128     -- Love and Ice(pt.2).\n    end\n\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.A_TEST_OF_TRUE_LOVE) then\n        bastokQuests = bastokQuests - 256       -- A Test of True Love(pt.1).\n        bastokQuests = bastokQuests - 512     -- A Test of True Love(pt.2).\n        bastokQuests = bastokQuests - 1024     -- A Test of True Love(pt.3).\n    end\n\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.LOVERS_IN_THE_DUSK) then\n        bastokQuests = bastokQuests - 2048      -- Lovers in the Dusk\n    end\n\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.GHOSTS_OF_THE_PAST) then\n        bastokQuests = bastokQuests - 4096      -- Ghosts of the Past(pt.1).\n        bastokQuests = bastokQuests - 8192     -- Ghosts of the Past(pt.2).\n    end\n\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.THE_FIRST_MEETING) then\n        bastokQuests = bastokQuests - 16384     -- The First Meeting(pt.1).\n        bastokQuests = bastokQuests - 32768     -- The First Meeting(pt.2).\n    end\n\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.AYAME_AND_KAEDE) then\n        bastokQuests = bastokQuests - 65536     -- Ayame and Kaede(pt.1).\n        bastokQuests = bastokQuests - 131072     -- Ayame and Kaede(pt.2).\n        bastokQuests = bastokQuests - 262144     -- Ayame and Kaede(pt.3).\n        bastokQuests = bastokQuests - 524288     -- Ayame and Kaede(pt.4).\n        bastokQuests = bastokQuests - 1048576     -- Ayame and Kaede(pt.5).\n    end\n-- *Need to determine the correct csid/appropriate options for this cutscene\n    --if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.TRIAL_BY_EARTH) then\n    --    bastokQuests = bastokQuests - 2097152   -- Trial by Earth.\n    --end\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.THE_WALLS_OF_YOUR_MIND) then\n        bastokQuests = bastokQuests - 4194304   -- The Walls of Your Mind(pt.1).\n        bastokQuests = bastokQuests - 8388608     -- The Walls of Your Mind(pt.2).\n        bastokQuests = bastokQuests - 16777216     -- The Walls of Your Mind(pt.3).\n    end\n\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.FADED_PROMISES) then\n        bastokQuests = bastokQuests - 33554432  -- Faded Promises.\n    end\n\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.OUT_OF_THE_DEPTHS) then\n        bastokQuests = bastokQuests - 67108864  -- Out of the Depths(pt.1).\n\n-- *Need to determine the appropriate options for this cutscene\n        -- bastokQuests = bastokQuests - 134217728 -- Out of the Depths(pt.2).\n    end\n\n    -- Other Quests.\n    local otherQuests = 0xFFFFFFFE\n    if player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.THE_PUPPET_MASTER) then\n        otherQuests = otherQuests - 2 -- The Puppet Master(pt.1).\n        otherQuests = otherQuests - 4 -- The Puppet Master(pt.2).\n    end\n\n    if player:hasCompletedQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.TWENTY_IN_PIRATE_YEARS) then\n        otherQuests = otherQuests - 8  -- 20 in Pirate Years(pt.1).\n        otherQuests = otherQuests - 16    -- 20 in Pirate Years(pt.2).\n    end\n\n    if player:hasCompletedQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.I_LL_TAKE_THE_BIG_BOX) then\n        otherQuests = otherQuests - 32 -- I'll Take the Big Box.\n    end\n\n-- *Need the correct csids\n    -- if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.CHASING_DREAMS) then\n    --     otherQuests = otherQuests - 64  -- Chasing Dreams(pt.1).\n    --     otherQuests = otherQuests - 128 -- Chasing Dreams(pt.2).\n    -- end\n\n-- *This quest, as of the time this script was written, is not yet defined.\n    -- if player:hasCompletedQuest(**Unknown**, MONSTROSITY) then\n    --     otherQuests = otherQuests - 256 -- Monstrosity.\n    -- end\n\n    -- Promathia Missions.\n    local promathiaMissions = 0xFFFFFFFE\n    if player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.THE_CALL_OF_THE_WYRMKING) then\n        promathiaMissions = promathiaMissions - 2 -- The Call of the Wyrmking.\n    end\n\n    if player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.THE_ENDURING_TUMULT_OF_WAR) then\n        promathiaMissions = promathiaMissions - 4 -- The Enduring Tumult of War.\n    end\n\n    -- Add-on Scenarios.\n    local addonScenarios = 0xFFFFFFFE\n    if player:hasCompletedMission(xi.mission.log_id.AMK, xi.mission.id.amk.DRENCHED_IT_BEGAN_WITH_A_RAINDROP) then\n        addonScenarios = addonScenarios - 2 -- Drenched! It Began with a Raindrop.\n    end\n\n-- *Need the correct csid\n--    if player:hasCompletedMission(xi.mission.log_id.AMK, xi.mission.id.amk.HASTEN_IN_A_JAM_IN_JEUNO) then\n--        addonScenarios = addonScenarios - 4 -- Hasten! In a Jam in Jeuno?\n--    end\n\n    -- Determine if any cutscenes are available for the player.\n    local gil = player:getGil()\n    if\n        bastokMissions == 0xFFFFFFFE and\n        bastokQuests == 0xFFFFFFFE and\n        otherQuests == 0xFFFFFFFE and\n        promathiaMissions == 0xFFFFFFFE and\n        addonScenarios == 0xFFFFFFFE\n    then -- Player has no cutscenes available to be viewed.\n        gil = 0 -- Setting gil to a value less than 10(cost) will trigger the appropriate response from this npc.\n    end\n\n    player:startEvent(260, bastokMissions, bastokQuests, otherQuests, promathiaMissions, addonScenarios, 0xFFFFFFFE, 10, gil)\nend\n\nentity.onEventUpdate = function(player, csid, option, npc)\n    if not player:delGil(10) then\n        player:setLocalVar('Dalba_PlayCutscene', 2)  -- Cancel the cutscene.\n        player:updateEvent(0)\n    else\n        player:setLocalVar('Dalba_PlayCutscene', 1)\n    end\nend\n\nlocal eventByOption =\n{\n    [  1] = {  1008, }, -- Fetichism\n    [  2] = {  1010, }, -- To the Forsaken Mines\n    [ 33] = {     2, }, -- Beauty and the Galka\n    [ 34] = {    52, }, -- Welcome to Bastok\n    [ 35] = {    55, }, -- Guest of Hauteur\n    [ 36] = {   133, }, -- Cid's Secret\n    [ 37] = {   136, }, -- The Usual\n    [ 38] = {   185, }, -- Love and Ice(pt.1)\n    [ 39] = {   186, }, -- Love and Ice(pt.2)\n    [ 40] = {   270, }, -- A Test of True Love(pt.1)\n    [ 41] = {   272, }, -- A Test of True Love(pt.2)\n    [ 42] = {   274, }, -- A Test of True Love(pt.3)\n    [ 43] = {   275, }, -- Lovers in the Dusk\n    [ 44] = {   231, }, -- Ghosts of the Past(pt.1)\n    [ 45] = {   232, }, -- Ghosts of the Past(pt.2)\n    [ 46] = {   233, }, -- The First Meeting(pt.1)\n    [ 47] = {   234, }, -- The First Meeting(pt.2)\n    [ 48] = {   240, }, -- Ayame and Kaede(pt.1)\n    [ 49] = {   241, }, -- Ayame and Kaede(pt.2)\n    [ 50] = {   242, }, -- Ayame and Kaede(pt.3)\n    [ 51] = {   245, }, -- Ayame and Kaede(pt.4)\n    [ 52] = {   246, }, -- Ayame and Kaede(pt.5)\n--  [ 53] = {   250, 0, xi.keyItem.TUNING_FORK_OF_EARTH, 1 }, -- Trial by Earth\n    [ 54] = {   286, }, -- The Walls of Your Mind(pt.1)\n    [ 55] = {   289, }, -- The Walls of Your Mind(pt.2)\n    [ 56] = {   290, }, -- The Walls of Your Mind(pt.3)\n    [ 57] = {   296, }, -- Faded Promises\n    [ 58] = {   307, }, -- Out of the Depths(pt.1)\n--  [ 59] = {   309, 0, 0, 0, 601 }, -- Out of the Depths(pt.2)\n    [ 65] = {   256, 0, xi.keyItem.TUNING_FORK_OF_EARTH, 0, 1169, 0, 0, 0, 0 }, -- The Puppet Master(pt.1)\n    [ 66] = {   258, }, -- The Puppet Master(pt.2)\n    [ 67] = {   261, }, -- 20 in Pirate Years(pt.1)\n    [ 68] = {   263, }, -- 20 in Pirate Years(pt.2)\n    [ 69] = {   264, }, -- I'll Take the Big Box\n--  [ 70] = {   ???, }, -- Chasing Dreams(pt.1)\n--  [ 71] = {   ???, }, -- Chasing Dreams(pt.2)\n--  [ 72] = {   ???, }, -- Monstrosity\n    [ 97] = {   305, }, -- The Call of the Wyrmking\n    [ 98] = {   306, }, -- The Enduring Tumult of War\n    [129] = { 30025, 0, 0, 0, 0, 0, 0, 236 }, -- Drenched! It Began with a Raindrop\n}\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if player:getLocalVar('Dalba_PlayCutscene') < 2 then\n        for k, eventData in pairs(eventByOption) do\n            if option == k then\n                player:startEvent(unpack(eventData))\n            end\n        end\n    end\n\n    player:setLocalVar('Dalba_PlayCutscene', 0)\nend\n\nreturn entity\n"},["scripts/zones/Port_Bastok/npcs/Ensetsu.lua"]={["Path"]="scripts/zones/Port_Bastok/npcs/Ensetsu.lua",["SHA256"]="fb56bf53a5aeade912014cb076515b3a2283e7044ceeaf86faa9389461336a77",["Text"]="-----------------------------------\n-- Area: Port Bastok\n--  NPC: Ensetsu\n-- Involved in Quest: 20 in Pirate Years\n-- !pos 32 -7 69 236\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local ayameAndKaede = player:getQuestStatus(xi.questLog.BASTOK, xi.quest.id.bastok.AYAME_AND_KAEDE)\n\n    if\n        ayameAndKaede == xi.questStatus.QUEST_COMPLETED and\n        player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.TWENTY_IN_PIRATE_YEARS) == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(247)\n    elseif player:getCharVar('twentyInPirateYearsCS') == 2 then\n        player:startEvent(262)\n    elseif player:getCharVar('twentyInPirateYearsCS') == 4 then\n        player:startEvent(263)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 262 then\n        player:setCharVar('twentyInPirateYearsCS', 3)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Port_San_dOria/npcs/Antreneau.lua"]={["Path"]="scripts/zones/Port_San_dOria/npcs/Antreneau.lua",["SHA256"]="53974aea0ed569dfb6afaaa861aeaaa5936f005083351f8e7fc0638f0f8009fd",["Text"]="-----------------------------------\n-- Area: Port San d'Oria\n--  NPC: Antreneau\n-- !pos -71 -5 -39 232\n-- Involved in Quests: A Taste For Meat, Over The Hills And Far Away\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    player:startEvent(532) -- What's this?  I don't need this.\nend\n\nentity.onTrigger = function(player, npc)\n    local aTasteForMeat = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_TASTE_FOR_MEAT)\n    local medicineWoman = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_MEDICINE_WOMAN)\n    local diaryPage = player:getCharVar('DiaryPage')\n    local fameLevel = player:getFameLevel(xi.fameArea.SANDORIA)\n\n    if\n        player:getCharVar('Quest[0][100]Option') == 0 and\n        aTasteForMeat == xi.questStatus.QUEST_COMPLETED and\n        fameLevel >= 8 and\n        medicineWoman == xi.questStatus.QUEST_COMPLETED and\n        diaryPage >= 4\n    then\n        local overTheHillsAndFarAway = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.OVER_THE_HILLS_AND_FAR_AWAY)\n\n        if overTheHillsAndFarAway == xi.questStatus.QUEST_AVAILABLE then\n            player:startEvent(725) -- Start\n        elseif overTheHillsAndFarAway == xi.questStatus.QUEST_ACCEPTED then\n            player:startEvent(726) -- Talks about the map.\n        elseif overTheHillsAndFarAway == xi.questStatus.QUEST_COMPLETED then\n            player:startEvent(727) -- Found his uncle Louverance.\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 725 then\n        player:addQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.OVER_THE_HILLS_AND_FAR_AWAY)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Port_San_dOria/npcs/Arminibit.lua"]={["Path"]="scripts/zones/Port_San_dOria/npcs/Arminibit.lua",["SHA256"]="7ec1f60f18ee9563500b7f49e20b2587932e6323b24463db737ab166bb95f699",["Text"]="-----------------------------------\n-- Area: Port San d'Oria\n--  NPC: Arminibit\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if\n        player:getMainLvl() >= 30 and\n        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_HOLY_CREST) == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(24)\n    else\n        player:startEvent(587)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 24 then\n        player:setCharVar('TheHolyCrest_Event', 1)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Port_San_dOria/npcs/Ceraulian.lua"]={["Path"]="scripts/zones/Port_San_dOria/npcs/Ceraulian.lua",["SHA256"]="ff9140a286b50adafe3c034d02f0400ce07f31c6df898bdaef89814ef9260d43",["Text"]="-----------------------------------\n-- Area: Port San d'Oria\n--  NPC: Ceraulian\n-- Involved in Quests: The Holy Crest, Knight Stalker\n-- !pos 0 -8 -122 232\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local stalkerStatus   = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.KNIGHT_STALKER)\n    local stalkerProgress = player:getCharVar('KnightStalker_Progress')\n\n    if\n        player:getMainLvl() >= xi.settings.main.ADVANCED_JOB_LEVEL and\n        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_HOLY_CREST) == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(24)\n\n    elseif\n        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.CHASING_QUOTAS) == xi.questStatus.QUEST_COMPLETED and\n        stalkerStatus == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(16) -- Fluff text until DRG AF3\n\n    -- Knight Stalker (DRG AF3)\n    elseif stalkerStatus == xi.questStatus.QUEST_ACCEPTED and stalkerProgress == 0 then\n        player:startEvent(19) -- Fetch the last Dragoon's helmet\n    elseif stalkerProgress == 1 then\n        if not player:hasKeyItem(xi.keyItem.CHALLENGE_TO_THE_ROYAL_KNIGHTS) then\n            player:startEvent(23) -- Reminder to get helmet\n        else\n            player:startEvent(20) -- Response if you try to turn in the challenge to Ceraulian\n        end\n    elseif player:getCharVar('KnightStalker_Option1') == 1 then\n        player:startEvent(22)\n    elseif stalkerStatus == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(21)\n\n    else\n        player:startEvent(587)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 24 then\n        player:setCharVar('TheHolyCrest_Event', 1)\n\n    -- Knight Stalker (DRG AF3)\n    elseif csid == 19 then\n        player:setCharVar('KnightStalker_Progress', 1)\n    elseif csid == 22 then\n        player:setCharVar('KnightStalker_Option1', 0)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Port_San_dOria/npcs/Regine.lua"]={["Path"]="scripts/zones/Port_San_dOria/npcs/Regine.lua",["SHA256"]="779a1a081f8dfdd8be8a94a8d3ab9476a84fbc337b32d5d533da16d50fd0bc97",["Text"]="-----------------------------------\n-- Area: Port San d'Oria\n--  NPC: Regine\n-- !pos 68 -9 -74 232\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local flyersForRegine = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.FLYERS_FOR_REGINE)\n\n    -- FLYERS FOR REGINE\n    if\n        flyersForRegine == xi.questStatus.QUEST_ACCEPTED and\n        npcUtil.tradeHas(trade, { { 'gil', 10 } })\n    then\n        if npcUtil.giveItem(player, xi.item.MAGICMART_FLYER) then\n            player:confirmTrade()\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local ffr = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.FLYERS_FOR_REGINE)\n\n    -- FLYERS FOR REGINE\n    if ffr == xi.questStatus.QUEST_AVAILABLE then -- ready to accept quest\n        player:startEvent(510, 2)\n    elseif\n        ffr == xi.questStatus.QUEST_ACCEPTED and\n        utils.mask.isFull(player:getCharVar('[ffr]deliveryMask'), 15)\n    then\n        -- all 15 flyers delivered\n        player:startEvent(603)\n    elseif\n        ffr == xi.questStatus.QUEST_ACCEPTED and\n        not player:hasItem(xi.item.MAGICMART_FLYER)\n    then -- on quest but out of flyers\n        player:startEvent(510, 3)\n\n    -- DEFAULT MENU\n    else\n        player:startEvent(510)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    -- FLYERS FOR REGINE\n    if csid == 510 and option == 2 then\n        if npcUtil.giveItem(player, { { xi.item.MAGICMART_FLYER, 1 }, { xi.item.MAGICMART_FLYER, 14 } })  then\n            player:addQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.FLYERS_FOR_REGINE)\n        end\n    elseif csid == 603 then\n        npcUtil.completeQuest(\n            player, xi.questLog.SANDORIA, xi.quest.id.sandoria.FLYERS_FOR_REGINE,\n            {\n                fame     = 20,\n                fameArea = xi.fameArea.SANDORIA,\n                gil      = 440,\n                title    = xi.title.ADVERTISING_EXECUTIVE,\n                var      = '[ffr]deliveryMask',\n            }\n        )\n\n    -- WHITE MAGIC SHOP\n    elseif csid == 510 and option == 0 then\n        local stockA =\n        {\n            { xi.item.SCROLL_OF_CURE,        67, 3, },\n            { xi.item.SCROLL_OF_CURE_II,    650, 2, },\n            { xi.item.SCROLL_OF_CURAGA,    1515, 3, },\n            { xi.item.SCROLL_OF_POISONA,    200, 3, },\n            { xi.item.SCROLL_OF_PARALYNA,   360, 3, },\n            { xi.item.SCROLL_OF_BLINDNA,   1100, 3, },\n            { xi.item.SCROLL_OF_DIA,         92, 3, },\n            { xi.item.SCROLL_OF_BANISH,     156, 2, },\n            { xi.item.SCROLL_OF_DIAGA,     1295, 1, },\n            { xi.item.SCROLL_OF_BANISHGA,  1295, 2, },\n            { xi.item.SCROLL_OF_PROTECT,    244, 3, },\n            { xi.item.SCROLL_OF_SHELL,     1760, 3, },\n            { xi.item.SCROLL_OF_BLINK,     2330, 2, },\n            { xi.item.SCROLL_OF_STONESKIN, 7806, 1, },\n            { xi.item.SCROLL_OF_AQUAVEIL,   400, 3, },\n            { xi.item.SCROLL_OF_SLOW,       930, 1, },\n        }\n        xi.shop.nation(player, stockA, xi.nation.SANDORIA)\n\n    -- BLACK MAGIC SHOP\n    elseif csid == 510 and option == 1 then\n        local stockB =\n        {\n            { xi.item.SCROLL_OF_STONE,      67, 3, },\n            { xi.item.SCROLL_OF_WATER,     156, 3, },\n            { xi.item.SCROLL_OF_AERO,      360, 3, },\n            { xi.item.SCROLL_OF_FIRE,      930, 3, },\n            { xi.item.SCROLL_OF_BLIZZARD, 1760, 3, },\n            { xi.item.SCROLL_OF_THUNDER,  3624, 3, },\n            { xi.item.SCROLL_OF_POISON,     92, 2, },\n            { xi.item.SCROLL_OF_BIO,       400, 2, },\n            { xi.item.SCROLL_OF_BLIND,     124, 1, },\n            { xi.item.SCROLL_OF_SLEEP,    2500, 2, },\n            { xi.item.SCROLL_OF_BURN,     5160, 3, },\n            { xi.item.SCROLL_OF_FROST,    4098, 3, },\n            { xi.item.SCROLL_OF_CHOKE,    2500, 3, },\n            { xi.item.SCROLL_OF_RASP,     2030, 3, },\n            { xi.item.SCROLL_OF_SHOCK,    1515, 3, },\n            { xi.item.SCROLL_OF_DROWN,    7074, 3, },\n        }\n        xi.shop.nation(player, stockB, xi.nation.SANDORIA)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Port_San_dOria/npcs/Vounebariont.lua"]={["Path"]="scripts/zones/Port_San_dOria/npcs/Vounebariont.lua",["SHA256"]="e1cf99b3a3f4aba80836a0b44201c45054591ca941ea3bda0a8faf9da7ad094d",["Text"]="-----------------------------------\n-- Area: Port San d'Oria\n--  NPC: Vounebariont\n-- Starts and Finishes Quest: Thick Shells\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.THICK_SHELLS) ~= xi.questStatus.QUEST_AVAILABLE then\n        if\n            trade:hasItemQty(xi.item.BEETLE_SHELL, 5) and\n            trade:getItemCount() == 5\n        then\n            player:startEvent(514)\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    if player:getFameLevel(xi.fameArea.SANDORIA) >= 2 then\n        player:startEvent(516)\n    else\n        player:startEvent(568)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 516 then\n        if player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.THICK_SHELLS) == xi.questStatus.QUEST_AVAILABLE then\n            player:addQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.THICK_SHELLS)\n        end\n    elseif csid == 514 then\n        if player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.THICK_SHELLS) == xi.questStatus.QUEST_ACCEPTED then\n            player:completeQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.THICK_SHELLS)\n            player:addFame(xi.fameArea.SANDORIA, 16)\n        else\n            player:addFame(xi.fameArea.SANDORIA, 16)\n        end\n\n        player:tradeComplete()\n        player:addTitle(xi.title.BUG_CATCHER)\n        npcUtil.giveCurrency(player, 'gil', 750)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Port_Windurst/npcs/Goltata.lua"]={["Path"]="scripts/zones/Port_Windurst/npcs/Goltata.lua",["SHA256"]="2486f5d0b989edbca3d6dcd68acb39fb8cf879ec18cf3b80a5140035c0faa0d6",["Text"]="-----------------------------------\n-- Area: Port Windurst\n--  NPC: Goltata\n--  Involved in Quests: Wonder Wands\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local wonderWands = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.WONDER_WANDS)\n\n    if wonderWands == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(257, 0, 0, 17091)\n    elseif wonderWands == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(269)\n    else\n        player:startEvent(232)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Port_Windurst/npcs/Hakkuru-Rinkuru.lua"]={["Path"]="scripts/zones/Port_Windurst/npcs/Hakkuru-Rinkuru.lua",["SHA256"]="b15c249380ae8c290b20991ffc3518ae181c02851a47858bda81098a14e905a5",["Text"]="-----------------------------------\n-- Area: Port Windurst\n--  NPC: Hakkuru-Rinkuru\n-- Involved In Quest: Making Amends\n-- Starts and Ends Quest: Wonder Wands\n-- !pos -111 -4 101 240\n-----------------------------------\nlocal ID = zones[xi.zone.PORT_WINDURST]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.WONDER_WANDS) == xi.questStatus.QUEST_ACCEPTED then\n        if\n            trade:hasItemQty(xi.item.OAK_STAFF, 1) and\n            trade:hasItemQty(xi.item.MYTHRIL_ROD, 1) and\n            trade:hasItemQty(xi.item.ROSE_WAND, 1) and\n            trade:getItemCount() == 3\n        then\n            -- Check that all 3 items have been traded, one each\n            player:setCharVar('SecondRewardVar', 1)\n            player:startEvent(265, 0, xi.item.OAK_STAFF, xi.item.MYTHRIL_ROD, xi.item.ROSE_WAND) -- Completion of quest cutscene for Wondering Wands\n        else\n            player:startEvent(260, 0, xi.item.OAK_STAFF, xi.item.MYTHRIL_ROD, xi.item.ROSE_WAND) -- Remind player which items are needed ifquest is accepted and items are not traded\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local makingAmends = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_AMENDS)\n    local makingAmens  = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_AMENS) --Second quest in series\n    local wonderWands  = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.WONDER_WANDS) --Third and final quest in series\n    local needToZone   = player:needToZone()\n    local pFame        = player:getFameLevel(xi.fameArea.WINDURST)\n\n--Begin Wonder Wands Section\n    if\n        makingAmends == xi.questStatus.QUEST_COMPLETED and\n        makingAmens == xi.questStatus.QUEST_COMPLETED and\n        wonderWands == xi.questStatus.QUEST_AVAILABLE and\n        pFame >= 5 and\n        not needToZone\n    then\n            player:startEvent(259) --Starts Wonder Wands\n    elseif wonderWands == xi.questStatus.QUEST_ACCEPTED then\n            player:startEvent(260) --Reminder for Wonder Wands\n    elseif wonderWands == xi.questStatus.QUEST_COMPLETED then\n        if player:getCharVar('SecondRewardVar') == 1 then\n            player:startEvent(267) --Initiates second reward ifWonder Wands has been completed.\n        end\n    end\n-- End Wonder Wands Section\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 259 and option == 1 then\n            player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.WONDER_WANDS)\n    elseif csid == 267 then\n        local rand = math.randomInt(1, 3) --Setup random variable to determine which 2 items are returned upon quest completion\n        if rand == 1 then\n            if player:getFreeSlotsCount() == 1 then\n                player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.MYTHRIL_ROD)\n            elseif player:getFreeSlotsCount() == 0 then\n                player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.OAK_STAFF)\n                player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.MYTHRIL_ROD)\n            else\n                player:addItem(xi.item.OAK_STAFF, 1)\n                player:addItem(xi.item.MYTHRIL_ROD, 1) --Returns the Oak Staff and the Mythril Rod\n                player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.OAK_STAFF)\n                player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.MYTHRIL_ROD)\n                player:setCharVar('SecondRewardVar', 0)\n            end\n        elseif rand == 2 then\n            if player:getFreeSlotsCount() == 1 then\n                player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.ROSE_WAND)\n            elseif player:getFreeSlotsCount() == 0 then\n                player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.OAK_STAFF)\n                player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.ROSE_WAND)\n            else\n                player:addItem(xi.item.OAK_STAFF, 1)\n                player:addItem(xi.item.ROSE_WAND, 1) --Returns the Oak Staff and the Rose Wand\n                player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.OAK_STAFF)\n                player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.ROSE_WAND)\n                player:setCharVar('SecondRewardVar', 0)\n            end\n        elseif rand == 3 then\n            if player:getFreeSlotsCount() == 1 then\n                player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.ROSE_WAND)\n            elseif player:getFreeSlotsCount() == 0 then\n                player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.MYTHRIL_ROD)\n                player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.ROSE_WAND)\n            else\n                player:addItem(xi.item.MYTHRIL_ROD, 1)\n                player:addItem(xi.item.ROSE_WAND, 1) --Returns the Rose Wand and the Mythril Rod\n                player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.MYTHRIL_ROD)\n                player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.ROSE_WAND)\n                player:setCharVar('SecondRewardVar', 0)\n            end\n        end\n    elseif csid == 265 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.NEW_MOON_ARMLETS)\n        else\n            player:tradeComplete()\n            npcUtil.giveCurrency(player, 'gil', 4800)\n            player:addItem(xi.item.NEW_MOON_ARMLETS)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.NEW_MOON_ARMLETS)\n            player:addFame(xi.fameArea.WINDURST, 50)\n            player:addTitle(xi.title.DOCTOR_SHANTOTTOS_GUINEA_PIG)\n            player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.WONDER_WANDS)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Port_Windurst/npcs/Kuroido-Moido.lua"]={["Path"]="scripts/zones/Port_Windurst/npcs/Kuroido-Moido.lua",["SHA256"]="ec03292f675659be59e8a5c6161fc59610d6935cefdd7b41c9832500301c4e74",["Text"]="-----------------------------------\n-- Area: Port Windurst (240)\n--  NPC: Kuriodo-Moido\n-- Involved In Quest: Making Amends, Wonder Wands,\n-- Starts and Finishes: Making Amens!, Orastery Woes\n-- !pos -112.5 -4.2 102.9 240\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local makingAmends = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_AMENDS) --First quest in series\n    local makingAmens = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_AMENS) --Second quest in series\n    local wonderWands = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.WONDER_WANDS) --Third and final quest in series\n    local pfame = player:getFameLevel(xi.fameArea.WINDURST)\n    local brokenWand = player:hasKeyItem(xi.keyItem.BROKEN_WAND)\n\n    if\n        makingAmends == xi.questStatus.QUEST_COMPLETED and\n        makingAmens == xi.questStatus.QUEST_AVAILABLE\n    then\n        if\n            pfame >= 4 and\n            not xi.quest.getMustZone(player, xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_AMENDS)\n        then\n            player:startEvent(280) -- Start Making Amens! if prerequisites are met\n        end\n    elseif\n        makingAmens == xi.questStatus.QUEST_ACCEPTED and\n        not brokenWand\n    then\n        player:startEvent(283) -- Reminder for Making Amens!\n    elseif\n        makingAmens == xi.questStatus.QUEST_ACCEPTED and\n        brokenWand\n    then -- Complete Making Amens!\n        player:startEvent(284, xi.settings.main.GIL_RATE * 6000)\n    elseif makingAmens == xi.questStatus.QUEST_COMPLETED then\n        if wonderWands == xi.questStatus.QUEST_ACCEPTED then -- During Wonder Wands dialogue\n            player:startEvent(261)\n        elseif wonderWands == xi.questStatus.QUEST_COMPLETED then -- Post Wonder Wands dialogue\n            player:startEvent(266)\n        else\n            player:startEvent(286, 0, 937) -- Post Making Amens! dialogue (before Wonder Wands)\n        end\n    else\n        local rand = math.randomInt(1, 2)\n        if rand == 1 then\n            player:startEvent(225)   -- Standard Conversation\n        else\n            player:startEvent(226)   -- Standard Conversation\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 280 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_AMENS)\n    elseif csid == 284 then\n        player:needToZone(true)\n        player:delKeyItem(xi.keyItem.BROKEN_WAND)\n        player:addTitle(xi.title.HAKKURU_RINKURUS_BENEFACTOR)\n        npcUtil.giveCurrency(player, 'gil', 6000)\n        player:addFame(xi.fameArea.WINDURST, 40)\n        player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_AMENS)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Port_Windurst/npcs/Ohruru.lua"]={["Path"]="scripts/zones/Port_Windurst/npcs/Ohruru.lua",["SHA256"]="5e4c748b40e7d86e9aea39c041c36c808053b250a7f835f7e10fe1cfebcac409",["Text"]="-----------------------------------\n-- Area: Port Windurst\n--  NPC: Ohruru\n-- Starts & Finishes Repeatable Quest: Catch me if you can\n-- Involved in Quest: Wonder Wands\n-- Note: Animation for his \"Cure\" is not functioning. Unable to capture option 1, so if the user says no, he heals them anyways.\n-- !pos -108 -5 94 240\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local catch = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CATCH_IT_IF_YOU_CAN)\n    local wonderWands = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.WONDER_WANDS)\n\n    if wonderWands == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(258, 0, 17053)\n    elseif catch == 0 then\n        local prog = player:getCharVar('QuestCatchItIfYouCan_var')\n        if prog == 0 then\n            player:startEvent(230) -- CATCH IT IF YOU CAN: Before Quest 1\n            player:setCharVar('QuestCatchItIfYouCan_var', 1)\n        elseif prog == 1 then\n            player:startEvent(253) -- CATCH IT IF YOU CAN: Before Start\n            player:setCharVar('QuestCatchItIfYouCan_var', 2)\n        elseif prog == 2 then\n            player:startEvent(231) -- CATCH IT IF YOU CAN: Before Quest 2\n        end\n\n    elseif\n        catch >= 1 and\n        (\n            player:hasStatusEffect(xi.effect.MUTE) or\n            player:hasStatusEffect(xi.effect.BANE) or\n            player:hasStatusEffect(xi.effect.PLAGUE)\n        )\n    then\n        player:startEvent(246) -- CATCH IT IF YOU CAN: Quest Turn In 1\n    elseif catch >= 1 and player:needToZone() then\n        player:startEvent(255) -- CATCH IT IF YOU CAN: After Quest\n    elseif\n        catch == 1 and\n        not player:hasStatusEffect(xi.effect.MUTE) and\n        not player:hasStatusEffect(xi.effect.BANE) and\n        not player:hasStatusEffect(xi.effect.PLAGUE)\n    then\n        local rand = math.randomInt(1, 2)\n        if rand == 1 then\n            player:startEvent(248) -- CATCH IT IF YOU CAN: During Quest 1\n        else\n            player:startEvent(251) -- CATCH IT IF YOU CAN: During Quest 2\n        end\n    elseif wonderWands == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(265)\n    else\n        player:startEvent(230) -- STANDARD CONVERSATION\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 231 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CATCH_IT_IF_YOU_CAN)\n    elseif csid == 246 and option == 0 then\n        player:needToZone(true)\n        if player:hasStatusEffect(xi.effect.MUTE) then\n            player:delStatusEffect(xi.effect.MUTE)\n            npcUtil.giveCurrency(player, 'gil', 1000)\n        elseif player:hasStatusEffect(xi.effect.BANE) then\n            player:delStatusEffect(xi.effect.BANE)\n            npcUtil.giveCurrency(player, 'gil', 1200)\n        elseif player:hasStatusEffect(xi.effect.PLAGUE) then\n            player:delStatusEffect(xi.effect.PLAGUE)\n            npcUtil.giveCurrency(player, 'gil', 1500)\n        end\n\n        player:setCharVar('QuestCatchItIfYouCan_var', 0)\n\n        if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CATCH_IT_IF_YOU_CAN) == xi.questStatus.QUEST_ACCEPTED then\n            player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CATCH_IT_IF_YOU_CAN)\n            player:addFame(xi.fameArea.WINDURST, 10)\n        else\n            player:addFame(xi.fameArea.WINDURST, 10)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Port_Windurst/npcs/Sigismund.lua"]={["Path"]="scripts/zones/Port_Windurst/npcs/Sigismund.lua",["SHA256"]="49e61f16687429af1afaecc1c0a3412f23313efa07b5308b42266721ea3983c3",["Text"]="-----------------------------------\n-- Area: Port Windurst\n--  NPC: Sigismund\n-- Starts and Finishes Quest: To Catch a Falling Star\n-- !pos -110 -10 82 240\n-----------------------------------\nlocal ID = zones[xi.zone.PORT_WINDURST]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local starstatus = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TO_CATCH_A_FALLING_STAR)\n    if\n        starstatus == 1 and\n        trade:hasItemQty(xi.item.STARFALL_TEAR, 1) and\n        trade:getItemCount() == 1 and\n        trade:getGil() == 0\n    then\n        player:startEvent(199) -- Quest Finish\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local starstatus = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TO_CATCH_A_FALLING_STAR)\n    if starstatus == xi.questStatus.QUEST_AVAILABLE then\n        player:startEvent(196, 0, xi.item.STARFALL_TEAR) -- Quest Start\n    elseif starstatus == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(197, 0, xi.item.STARFALL_TEAR) -- Quest Reminder\n    elseif\n        starstatus == xi.questStatus.QUEST_COMPLETED and\n        player:getCharVar('QuestCatchAFallingStar_prog') > 0\n    then\n        player:startEvent(200) -- After Quest\n        player:setCharVar('QuestCatchAFallingStar_prog', 0)\n    else\n        player:startEvent(357)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 196 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.TO_CATCH_A_FALLING_STAR)\n    elseif csid == 199 then\n        player:tradeComplete()\n        player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.TO_CATCH_A_FALLING_STAR)\n        player:addFame(xi.fameArea.WINDURST, 20)\n        player:addItem(xi.item.FISH_SCALE_SHIELD)\n        player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.FISH_SCALE_SHIELD)\n        player:setCharVar('QuestCatchAFallingStar_prog', 2)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Port_Windurst/npcs/Tohopka.lua"]={["Path"]="scripts/zones/Port_Windurst/npcs/Tohopka.lua",["SHA256"]="167a196eb23ee1c44d8476e998b6946e3ff97809f26a97a6f2aee50965c502ab",["Text"]="-----------------------------------\n-- Area: Port Windurst\n-- NPC : Tohopka\n-- !pos -105.723 -10 83.813 240\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local starStatus = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TO_CATCH_A_FALLING_STAR)\n\n    if starStatus == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(198, 0, 546, 868)\n    else\n        player:startEvent(358)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Port_Windurst/npcs/Tokaka.lua"]={["Path"]="scripts/zones/Port_Windurst/npcs/Tokaka.lua",["SHA256"]="00bfd5090ffb185a063aaa3078b2d5b65157b6dc88f178fa9ea7f75245533432",["Text"]="-----------------------------------\n-- Area: Port Windurst\n--  NPC: Tokaka\n-- Starts & Finishes Repeatable Quest: Something Fishy\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local tokakaSpokenTo = player:getCharVar('TokakaSpokenTo')\n    local needToZone     = player:needToZone()\n\n    if tokakaSpokenTo == 1 and not needToZone then\n        if\n            trade:hasItemQty(xi.item.BASTORE_SARDINE_1, 1) and\n            trade:getItemCount() == 1\n        then\n            player:startEvent(210, xi.settings.main.GIL_RATE * 70, xi.item.BASTORE_SARDINE_1)\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local somethingFishy = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.SOMETHING_FISHY)\n\n    if somethingFishy >= xi.questStatus.QUEST_ACCEPTED then\n        if player:needToZone() then\n            player:startEvent(211)\n        else\n            player:startEvent(209, 0, xi.item.BASTORE_SARDINE_1)\n        end\n    elseif somethingFishy == xi.questStatus.QUEST_AVAILABLE then\n        player:startEvent(208, 0, xi.item.BASTORE_SARDINE_1)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 208 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.SOMETHING_FISHY)\n        player:setCharVar('TokakaSpokenTo', 1)\n    elseif csid == 210 then\n        local somethingFishy = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.SOMETHING_FISHY)\n\n        if somethingFishy == xi.questStatus.QUEST_ACCEPTED then\n            player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.SOMETHING_FISHY)\n            player:addFame(xi.fameArea.WINDURST, 10)\n        else\n            player:addFame(xi.fameArea.WINDURST, 10)\n        end\n\n        player:tradeComplete()\n        player:addGil(xi.settings.main.GIL_RATE * 70)\n        player:setCharVar('TokakaSpokenTo', 0)\n        player:needToZone(true)\n    elseif csid == 209 then\n        player:setCharVar('TokakaSpokenTo', 1)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Port_Windurst/npcs/Yaman-Hachuman.lua"]={["Path"]="scripts/zones/Port_Windurst/npcs/Yaman-Hachuman.lua",["SHA256"]="3d72c89658ca2c0204273afd2c81ede76f24c9bc9e39d7cee75e139090400d90",["Text"]="-----------------------------------\n-- Area: Port Windurst\n--  NPC: Yaman-Hachuman\n--  Involved in Quests: Wonder Wands\n-- !pos -101.209 -4.25 110.886 240\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local wonderWands = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.WONDER_WANDS)\n\n    if wonderWands == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(256, 0, 0, 0, 17061)\n    elseif wonderWands == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(268)\n    else\n        player:startEvent(233)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Port_Windurst/npcs/Yujuju.lua"]={["Path"]="scripts/zones/Port_Windurst/npcs/Yujuju.lua",["SHA256"]="c939cd5dee707449ef50b8fd067ec014765fd34c925b0724848dbd7ce1b5633b",["Text"]="-----------------------------------\n-- Area: Port Windurst\n--  NPC: Yujuju\n--  Involved In Quest: Making Headlines\n-- !pos 201.523 -4.785 138.978 240\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local makingHeadlines = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_HEADLINES)\n\n    if makingHeadlines == xi.questStatus.QUEST_ACCEPTED then\n        -- bitmask of progress: 0 = Kyume-Romeh, 1 = Yuyuju, 2 = Hiwom-Gomoi, 3 = Umumu, 4 = Mahogany Door\n        local prog = player:getCharVar('QuestMakingHeadlines_var')\n\n        if not utils.mask.getBit(prog, 1) then\n            player:startEvent(314) -- Get Scoop\n        else\n            player:startEvent(315) -- After receiving scoop\n        end\n    else\n        player:startEvent(340) -- Standard Conversation\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 314 then\n        npcUtil.giveKeyItem(player, xi.keyItem.PORT_WINDURST_SCOOP)\n        player:setCharVar('QuestMakingHeadlines_var', utils.mask.setBit(player:getCharVar('QuestMakingHeadlines_var'), 1, true))\n    end\nend\n\nreturn entity\n"},["scripts/zones/Qufim_Island/npcs/Transcendental_Radiance.lua"]={["Path"]="scripts/zones/Qufim_Island/npcs/Transcendental_Radiance.lua",["SHA256"]="0420e98832a0cb02d6498f9f38379aa3e3b874ba47082984d683557f3ca36b3c",["Text"]="-----------------------------------\n-- Area: Qufim Island (126)\n--  NPC: Transcendental Radiance\n-- !pos -259.433 -21.581 220.498 126\n-- Warp to Abyssea - Empyreal Paradox.\n-- Requires Beneath a Blood Red Sky accepted or completed.\n-- Entry: Crimson Traverser Stone (free) or 1+ Traverser Stone and 10000+ cruor.\n-- Event 46 = completed quest dialogue; Event 47 = accepted (not completed) dialogue.\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local status = player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.BENEATH_A_BLOOD_RED_SKY)\n    if status < xi.questStatus.QUEST_ACCEPTED then\n        return\n    end\n\n    local hasCrimson = player:hasKeyItem(xi.keyItem.CRIMSON_TRAVERSER_STONE)\n    local traverserStones = xi.abyssea.getHeldTraverserStones(player)\n    local cruor = player:getCurrency('cruor')\n\n    if not hasCrimson and (traverserStones < 1 or cruor < 10000) then\n        return\n    end\n\n    if status >= xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(46, 0, 0, cruor, 10000, 0, 0, 0)\n    else\n        player:startEvent(47, 0, 0, cruor, 10000, 0, 0, 0)\n    end\nend\n\nentity.onEventUpdate = function(player, csid, option, npc)\n    local cruor = player:getCurrency('cruor')\n    player:updateEvent(7, 1, cruor, 10000, 0, 848559, 4095, 131186)\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if option ~= 1 then\n        return\n    end\n\n    if not player:hasKeyItem(xi.keyItem.CRIMSON_TRAVERSER_STONE) then\n        if\n            player:getCurrency('cruor') >= 10000 and\n            xi.abyssea.getHeldTraverserStones(player) >= 1\n        then\n            player:delCurrency('cruor', 10000)\n            npcUtil.giveKeyItem(player, xi.keyItem.CRIMSON_TRAVERSER_STONE)\n            xi.abyssea.spendTravStones(player, 1)\n        else\n            return\n        end\n    end\n\n    player:setPos(540, -500, -571, 64, xi.zone.ABYSSEA_EMPYREAL_PARADOX)\nend\n\nreturn entity\n"},["scripts/zones/Rabao/npcs/Agado-Pugado.lua"]={["Path"]="scripts/zones/Rabao/npcs/Agado-Pugado.lua",["SHA256"]="54108e7d998d34d14e5185b6b17dcae83795581321d3a489019747c0529bc38c",["Text"]="-----------------------------------\n-- Area: Rabao\n--  NPC: Agado-Pugado\n-- Starts and Finishes Quest: Trial by Wind\n-- !pos -17 7 -10 247\n-----------------------------------\nlocal ID = zones[xi.zone.RABAO]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local trialByWind = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_BY_WIND)\n    local carbuncleDebacle = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CARBUNCLE_DEBACLE)\n    local carbuncleDebacleProgress = player:getCharVar('CarbuncleDebacleProgress')\n\n    -----------------------------------\n    -- Carbuncle Debacle\n    if\n        carbuncleDebacle == xi.questStatus.QUEST_ACCEPTED and\n        carbuncleDebacleProgress == 5 and\n        player:hasKeyItem(xi.keyItem.DAZE_BREAKER_CHARM)\n    then\n        player:startEvent(86) -- get the wind pendulum, lets go to Cloister of Gales\n    elseif\n        carbuncleDebacle == xi.questStatus.QUEST_ACCEPTED and\n        carbuncleDebacleProgress == 6\n    then\n        if not player:hasItem(xi.item.WIND_PENDULUM) then\n            player:startEvent(87, 0, xi.item.WIND_PENDULUM, 0, 0, 0, 0, 0, 0) -- \"lost the pendulum?\" This one too~???\n        else\n            player:startEvent(88) -- reminder to go to Cloister of Gales\n        end\n    -----------------------------------\n    -- Trial by Wind\n    elseif\n        (trialByWind == xi.questStatus.QUEST_AVAILABLE and player:getFameLevel(xi.fameArea.SELBINA_RABAO) >= 5) or\n        (trialByWind == xi.questStatus.QUEST_COMPLETED and GetSystemTime() > player:getCharVar('TrialByWind_date'))\n    then\n        player:startEvent(66, 0, 331) -- Start and restart quest 'Trial by Wind'\n    elseif\n        trialByWind == xi.questStatus.QUEST_ACCEPTED and\n        not player:hasKeyItem(xi.keyItem.TUNING_FORK_OF_WIND) and\n        not player:hasKeyItem(xi.keyItem.WHISPER_OF_GALES)\n    then\n        player:startEvent(107, 0, 331) -- Defeat against Avatar : Need new Fork\n    elseif\n        trialByWind == xi.questStatus.QUEST_ACCEPTED and\n        not player:hasKeyItem(xi.keyItem.WHISPER_OF_GALES)\n    then\n        player:startEvent(67, 0, 331, 3)\n    elseif\n        trialByWind == xi.questStatus.QUEST_ACCEPTED and\n        player:hasKeyItem(xi.keyItem.WHISPER_OF_GALES)\n    then\n        local numitem = 0\n\n        if player:hasItem(xi.item.GARUDAS_DAGGER) then\n            numitem = numitem + 1\n        end  -- Garuda's Dagger\n\n        if player:hasItem(xi.item.WIND_BELT) then\n            numitem = numitem + 2\n        end  -- Wind Belt\n\n        if player:hasItem(xi.item.WIND_RING) then\n            numitem = numitem + 4\n        end  -- Wind Ring\n\n        if player:hasItem(xi.item.BOTTLE_OF_BUBBLY_WATER) then\n            numitem = numitem + 8\n        end   -- Bubbly Water\n\n        if player:hasSpell(xi.magic.spell.GARUDA) then\n            numitem = numitem + 32\n        end  -- Ability to summon Garuda\n\n        player:startEvent(69, 0, 331, 3, 0, numitem)\n    else\n        player:startEvent(70) -- Standard dialog\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 66 and option == 1 then\n        if player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_BY_WIND) == xi.questStatus.QUEST_COMPLETED then\n            player:delQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_BY_WIND)\n        end\n\n        player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_BY_WIND)\n        player:setCharVar('TrialByWind_date', 0)\n        npcUtil.giveKeyItem(player, xi.keyItem.TUNING_FORK_OF_WIND)\n    elseif csid == 107 then\n        npcUtil.giveKeyItem(player, xi.keyItem.TUNING_FORK_OF_WIND)\n    elseif csid == 69 then\n        local item = 0\n        if option == 1 then\n            item = xi.item.GARUDAS_DAGGER\n        elseif option == 2 then\n            item = xi.item.WIND_BELT\n        elseif option == 3 then\n            item = xi.item.WIND_RING\n        elseif option == 4 then\n            item = xi.item.BOTTLE_OF_BUBBLY_WATER\n        end\n\n        if player:getFreeSlotsCount() == 0 and (option ~= 5 or option ~= 6) then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, item)\n        else\n            if option == 5 then\n                npcUtil.giveCurrency(player, 'gil', 10000)\n            elseif option == 6 then\n                player:addSpell(xi.magic.spell.GARUDA) -- Garuda Spell\n                player:messageSpecial(ID.text.GARUDA_UNLOCKED, 0, 0, 3)\n            else\n                player:addItem(item)\n                player:messageSpecial(ID.text.ITEM_OBTAINED, item) -- Item\n            end\n\n            player:addTitle(xi.title.HEIR_OF_THE_GREAT_WIND)\n            player:delKeyItem(xi.keyItem.WHISPER_OF_GALES) --Whisper of Gales, as a trade for the above rewards\n            player:setCharVar('TrialByWind_date', JstMidnight())\n            player:addFame(xi.fameArea.SANDORIA, 30)\n            player:addFame(xi.fameArea.BASTOK, 30)\n            player:completeQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_BY_WIND)\n        end\n    elseif csid == 86 or csid == 87 then\n        if player:getFreeSlotsCount() ~= 0 then\n            player:addItem(xi.item.WIND_PENDULUM)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.WIND_PENDULUM)\n            player:setCharVar('CarbuncleDebacleProgress', 6)\n        else\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.WIND_PENDULUM)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Rabao/npcs/Edigey.lua"]={["Path"]="scripts/zones/Rabao/npcs/Edigey.lua",["SHA256"]="8c34804348477dd435e32174eb8a8520b8049aaccf821e081dcdc0c02390d7c6",["Text"]="-----------------------------------\n-- Area: Rabao\n--  NPC: Edigey\n-- Starts and Ends Quest: Don't Forget the Antidote\n-----------------------------------\nlocal ID = zones[xi.zone.RABAO]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local forgetTheAntidote = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.DONT_FORGET_THE_ANTIDOTE)\n\n    if\n        (forgetTheAntidote == xi.questStatus.QUEST_ACCEPTED or forgetTheAntidote == xi.questStatus.QUEST_COMPLETED) and\n        trade:hasItemQty(xi.item.VIAL_OF_DESERT_VENOM, 1) and\n        trade:getItemCount() == 1\n    then\n        player:startEvent(4, 0, xi.item.VIAL_OF_DESERT_VENOM)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local forgetTheAntidote = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.DONT_FORGET_THE_ANTIDOTE)\n\n    if\n        forgetTheAntidote == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.SELBINA_RABAO) >= 4\n    then\n        player:startEvent(2, 0, xi.item.VIAL_OF_DESERT_VENOM)\n    elseif forgetTheAntidote == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(3, 0, xi.item.VIAL_OF_DESERT_VENOM)\n    elseif forgetTheAntidote == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(5, 0, xi.item.VIAL_OF_DESERT_VENOM)\n    else\n        player:startEvent(50)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 2 and option == 1 then\n        player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.DONT_FORGET_THE_ANTIDOTE)\n        player:setCharVar('DontForgetAntidoteVar', 1)\n    elseif csid == 4 and player:getCharVar('DontForgetAntidoteVar') == 1 then --If completing for the first time\n        player:setCharVar('DontForgetAntidoteVar', 0)\n        player:tradeComplete()\n        player:addTitle(xi.title.DESERT_HUNTER)\n        player:addItem(xi.item.DOTANUKI) -- Dotanuki\n        player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.DOTANUKI)\n        player:completeQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.DONT_FORGET_THE_ANTIDOTE)\n        player:addFame(xi.fameArea.SANDORIA, 5)\n        player:addFame(xi.fameArea.BASTOK, 5)\n    elseif csid == 4 then --Subsequent completions\n        player:tradeComplete()\n        npcUtil.giveCurrency(player, 'gil', 1800)\n        player:addFame(xi.fameArea.SANDORIA, 5)\n        player:addFame(xi.fameArea.BASTOK, 5)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Rabao/npcs/Irmilant.lua"]={["Path"]="scripts/zones/Rabao/npcs/Irmilant.lua",["SHA256"]="d251c6790b96abe7fd01dca33c3771d38b982854b255d368a0c16a50a3ca7ae3",["Text"]="-----------------------------------\n-- Area: Rabao\n--  NPC: Irmilant\n-- Starts and Ends Quests: The Immortal Lu Shang and Indomitable Spirit\n-- !pos 3.78 9.54 56.21 247\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local Indomitable = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.INDOMITABLE_SPIRIT)\n    local ImmortalLuShang = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_IMMORTAL_LU_SHANG)\n\n    if\n        (ImmortalLuShang == xi.questStatus.QUEST_ACCEPTED or ImmortalLuShang == xi.questStatus.QUEST_COMPLETED) and\n        npcUtil.tradeHas(trade, { 720, xi.item.BROKEN_LU_SHANGS_FISHING_ROD, xi.item.LIGHT_CRYSTAL })\n    then\n        player:startEvent(78)\n    elseif\n        (Indomitable == xi.questStatus.QUEST_ACCEPTED or Indomitable == xi.questStatus.QUEST_COMPLETED) and\n        npcUtil.tradeHas(trade, { 1837, 1826 })\n    then\n        player:startEvent(132)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local Indomitable = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.INDOMITABLE_SPIRIT)\n    local ImmortalLuShang = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_IMMORTAL_LU_SHANG)\n    local indomitableTimer = player:getCharVar('IndomitableSpiritTimer')\n\n    if\n        player:hasItem(xi.item.BROKEN_LU_SHANGS_FISHING_ROD) and\n        (ImmortalLuShang == xi.questStatus.QUEST_AVAILABLE or ImmortalLuShang == xi.questStatus.QUEST_COMPLETED)\n    then\n        player:startEvent(77) --Offer the quest if the player has the broken rod\n    elseif\n        player:hasKeyItem(xi.keyItem.SERPENT_RUMORS) and\n        Indomitable == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(131) --Begins Indomitable Spirit\n    elseif indomitableTimer ~= 0 and indomitableTimer > GetSystemTime() then\n        player:startEvent(133) --Asks the player to wait (next CQ tally)\n    elseif indomitableTimer ~= 0 then\n        player:startEvent(134) --Ends the Quest\n    elseif Indomitable == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(135) --Dialogue for those who have completed Indomitable Spirit\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 77 then\n        player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_IMMORTAL_LU_SHANG)\n    elseif\n        csid == 78 and\n        npcUtil.completeQuest(player, xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_IMMORTAL_LU_SHANG, { item = 17386, title = xi.title.THE_IMMORTAL_FISHER_LU_SHANG })\n    then\n        player:addFame(xi.fameArea.SANDORIA, 10)\n        player:addFame(xi.fameArea.BASTOK, 10)\n        player:confirmTrade()\n    elseif csid == 131 then\n        player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.INDOMITABLE_SPIRIT)\n    elseif csid == 132 then\n        player:confirmTrade()\n        player:setCharVar('IndomitableSpiritTimer', NextConquestTally()) -- Player must wait until next CQ tally\n    elseif csid == 134 then\n        if npcUtil.completeQuest(player, xi.questLog.OUTLANDS, xi.quest.id.outlands.INDOMITABLE_SPIRIT, { item = 17011, title = xi.title.INDOMITABLE_FISHER, var = 'IndomitableSpiritTimer' }) then\n            player:addFame(xi.fameArea.SANDORIA, 10)\n            player:addFame(xi.fameArea.BASTOK, 10)\n        end\n    end\nend\n\nreturn entity\n"}};
